// ด่าน ① Consent ② Opt-out/Unsubscribe ③ Frequency cap (≤2/วัน, ≤5/สัปดาห์)
// ตรวจก่อนส่งทุกครั้ง — ถอนความยินยอม = หยุดทุกช่องทางทันที
const res = $input.first().json || {};
const due = Array.isArray(res) ? res : (res.followUps || res.items || res.data || []);
const CAP_DAY = 2, CAP_WEEK = 5;
const out = [];
const skipped = { consent: 0, cap: 0, noChannel: 0 };
for (const f of due) {
  const consentOk = (f.consentMarketing === true || f.consent === true)
    && f.unsubscribed !== true && f.optOut !== true && f.doNotContact !== true;
  const sentToday = Number(f.sentToday || 0) || 0;
  const sentThisWeek = Number(f.sentThisWeek || 0) || 0;
  const capOk = sentToday < CAP_DAY && sentThisWeek < CAP_WEEK;
  const contact = f.lineUserId || f.phone || f.email || null;
  if (!consentOk) { skipped.consent++; continue; }
  if (!capOk) { skipped.cap++; continue; }
  if (!contact) { skipped.noChannel++; continue; }
  const prospectId = f.prospectId || f.prospect_id || null;
  out.push({ json: {
    followUpId: f.followUpId || f.id, prospectId: prospectId, name: f.name || null,
    dayOffset: f.dayOffset || null,
    channel: String(f.channel || (f.lineUserId ? 'LINE' : 'EMAIL')).toUpperCase(),
    lineUserId: f.lineUserId || null, phone: f.phone || null, email: f.email || null,
    topic: f.topic || (f.interests || [])[0] || null, interests: f.interests || [],
    lastContactAt: f.lastContactAt || f.sentAt || null,
    sentToday: sentToday, sentThisWeek: sentThisWeek, caps: { perDay: CAP_DAY, perWeek: CAP_WEEK },
    scheduledAt: f.scheduledAt || null,
    unsubscribeUrl: 'https://ai-insurance-network-tree.vercel.app/unsubscribe?p=' + (prospectId || '')
  }, pairedItem: { item: 0 } });
}
if (out.length === 0) return [{ json: { none: true, reason: 'ไม่มี follow-up ที่ผ่านด่านในรอบนี้', skipped: skipped, checked: due.length } }];
return out;

// อ่านข้อความจาก AI + ต่อท้ายช่องทางยกเลิกการติดตาม (บังคับทุกข้อความ)
const leads = $('ตรวจ Consent + Opt-out + Frequency cap').all();
const items = $input.all();
const FOOTER = ' — ถ้าไม่ต้องการรับข้อความอีก พิมพ์ STOP หรือกดยกเลิกได้ที่: ';
const out = [];
items.forEach(function (it, i) {
  const lead = (leads[i] && leads[i].json) || {};
  if (lead.none || !lead.followUpId) return;
  const raw = String(it.json.answer || it.json.text || it.json.content || '');
  const m = raw.match(/\{[\s\S]*\}/);
  let parsed = null;
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e) { parsed = null; } }
  let body = (parsed && (parsed.message || parsed.text)) ? String(parsed.message || parsed.text) : '';
  if (!body) body = 'สวัสดีครับคุณ ' + (lead.name || '') + ' ถ้าต้องการให้ทีมงานส่งข้อมูลเพิ่มเติมหรือนัดหมาย ทักกลับได้เลยครับ';
  body = body.replace(/\s+/g, ' ').slice(0, 700);
  const subject = (parsed && parsed.subject) ? String(parsed.subject).slice(0, 120) : 'ข้อมูลที่คุณสนใจจากทีมงาน';
  out.push({ json: Object.assign({}, lead, {
    message: body + FOOTER + lead.unsubscribeUrl,
    messageText: body, subject: subject, aiOk: !!parsed, at: new Date().toISOString()
  }), pairedItem: { item: i } });
});
if (out.length === 0) return [{ json: { none: true, reason: 'ไม่มีข้อความที่ต้องส่งในรอบนี้' } }];
return out;

// สรุปผลการส่ง follow-up (อ่านจากโหนดบันทึกผลการส่ง)
const all = $('บันทึกผลการส่ง (/api/followup/result)').all();
let sent = 0, fail = 0, firstError = null;
for (const it of all) {
  const j = it.json || {};
  const c = j.statusCode === undefined ? null : Number(j.statusCode);
  const ok = j.ok === true || (c !== null && c >= 200 && c < 300);
  if (ok) sent++;
  else { fail++; if (!firstError) firstError = String(j.error || j.message || ('HTTP ' + c)).slice(0, 300); }
}
return [{ json: {
  ok: fail === 0, workflow: '05-followup', stage: 'send_followup',
  detail: 'ส่งข้อความสำเร็จ ' + sent + ' ราย / ล้มเหลว ' + fail + ' ราย' + (firstError ? ' — ' + firstError : ''),
  sent: sent, failed: fail, firstError: firstError,
  alertText: (fail === 0 ? 'Follow-up รอบล่าสุดส่งสำเร็จ ' : 'แจ้งเตือน: Follow-up ส่งไม่สำเร็จ ') + sent + ' ราย',
  at: new Date().toISOString()
} }];
